class Solution {
public:
    int countPalindromes(std::string s) {
        int n = s.length();
        if (n < 5) return 0;
        const int MOD = 1000000007;
        std::vector<std::vector<std::vector<int>>> pref(n, std::vector<std::vector<int>>(10, std::vector<int>(10, 0)));
        std::vector<std::vector<std::vector<int>>> suff(n, std::vector<std::vector<int>>(10, std::vector<int>(10, 0)));
        std::vector<int> cnt(10, 0);
        for (int i = 0; i < n; ++i) {
            int d = s[i] - '0';
            if (i > 0) {
                pref[i] = pref[i - 1];
                for (int j = 0; j < 10; ++j) {
                    pref[i][j][d] = (pref[i][j][d] + cnt[j]) % MOD;
                }
            }
            cnt[d]++;
        }
        std::fill(cnt.begin(), cnt.end(), 0);
        for (int i = n - 1; i >= 0; --i) {
            int d = s[i] - '0';
            if (i < n - 1) {
                suff[i] = suff[i + 1];
                for (int k = 0; k < 10; ++k) {
                    suff[i][d][k] = (suff[i][d][k] + cnt[k]) % MOD;
                }
            }
            cnt[d]++;
        }
        long long ans = 0;
        for (int i = 2; i < n - 2; ++i) {
            for (int j = 0; j < 10; ++j) {
                for (int k = 0; k < 10; ++k) {
                    ans = (ans + 1LL * pref[i - 1][j][k] * suff[i + 1][k][j]) % MOD;
                }
            }
        }
        return ans;
    }
};

class Solution {
    public int countPalindromes(String s) {
        int n = s.length();
        if (n < 5) return 0;
        int MOD = 1_000_000_007;
        int[][][] pref = new int[n][10][10];
        int[][][] suff = new int[n][10][10];
        int[] cnt = new int[10];
        for (int i = 0; i < n; i++) {
            int d = s.charAt(i) - '0';
            if (i > 0) {
                for (int j = 0; j < 10; j++) {
                    for (int k = 0; k < 10; k++) {
                        pref[i][j][k] = pref[i - 1][j][k];
                    }
                }
                for (int j = 0; j < 10; j++) {
                    pref[i][j][d] = (pref[i][j][d] + cnt[j]) % MOD;
                }
            }
            cnt[d]++;
        }
        java.util.Arrays.fill(cnt, 0);
        for (int i = n - 1; i >= 0; i--) {
            int d = s.charAt(i) - '0';
            if (i < n - 1) {
                for (int j = 0; j < 10; j++) {
                    for (int k = 0; k < 10; k++) {
                        suff[i][j][k] = suff[i + 1][j][k];
                    }
                }
                for (int k = 0; k < 10; k++) {
                    suff[i][d][k] = (suff[i][d][k] + cnt[k]) % MOD;
                }
            }
            cnt[d]++;
        }
        long ans = 0;
        for (int i = 2; i < n - 2; i++) {
            for (int j = 0; j < 10; j++) {
                for (int k = 0; k < 10; k++) {
                    ans = (ans + (long) pref[i - 1][j][k] * suff[i + 1][k][j]) % MOD;
                }
            }
        }
        return (int) ans;
    }
}

